package com.aistudyassistance.backend.project;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/projects") public class ProjectController{final ProjectRepository r;ProjectController(ProjectRepository r){this.r=r;}@GetMapping List<Project>all(){return r.findAll();}@GetMapping("/{id}")Project one(@PathVariable Long id){return r.findById(id).orElseThrow();}@PostMapping@ResponseStatus(HttpStatus.CREATED)Project add(@RequestBody Project p){p.id=null;return r.save(p);}@PutMapping("/{id}")Project put(@PathVariable Long id,@RequestBody Project p){p.id=id;return r.save(p);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void del(@PathVariable Long id){r.deleteById(id);}}
